"""Run the unchanged real NVDA probe plus readonly installed-DMLX checks.

This controller wrapper adds observations only. It does not edit the addon,
release resource, driver preferences, utterances, data or speech timing.
A real installed version11 descriptor/data/manager is required.
"""
from __future__ import annotations
import importlib.util
from pathlib import Path

PROBE_FUNCTION="\nNATIVE_SOURCE_CASES=[{\"word\":\"ольсену\",\"memberships\":[\"uk\"]},{\"word\":\"галапагосе\",\"memberships\":[\"uk\"]},{\"word\":\"витівкових\",\"memberships\":[\"uk\"]},{\"word\":\"доктрину\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"мегакрутими\",\"memberships\":[\"uk\"]},{\"word\":\"утеплювавсь\",\"memberships\":[\"uk\"]},{\"word\":\"рушникосушки\",\"memberships\":[\"uk\"]},{\"word\":\"яснесенькою\",\"memberships\":[\"uk\"]},{\"word\":\"вигибатимеш\",\"memberships\":[\"uk\"]},{\"word\":\"курятинами\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"висловлень\",\"memberships\":[\"uk\"]},{\"word\":\"малопривабливій\",\"memberships\":[\"uk\"]},{\"word\":\"детектуй\",\"memberships\":[\"uk\"]},{\"word\":\"погамував\",\"memberships\":[\"uk\"]},{\"word\":\"зализуватимусь\",\"memberships\":[\"uk\"]},{\"word\":\"проголених\",\"memberships\":[\"uk\"]},{\"word\":\"попідливано\",\"memberships\":[\"uk\"]},{\"word\":\"найпискливіш\",\"memberships\":[\"uk\"]},{\"word\":\"розплішіться\",\"memberships\":[\"uk\"]},{\"word\":\"оберстдорфові\",\"memberships\":[\"uk\"]},{\"word\":\"без'ядерності\",\"memberships\":[\"uk\"]},{\"word\":\"озимій\",\"memberships\":[\"uk\"]},{\"word\":\"променітимем\",\"memberships\":[\"uk\"]},{\"word\":\"дідуню\",\"memberships\":[\"uk\"]},{\"word\":\"плагіоклазі\",\"memberships\":[\"uk\"]},{\"word\":\"непальцем\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"бережечками\",\"memberships\":[\"uk\"]},{\"word\":\"драйвували\",\"memberships\":[\"uk\"]},{\"word\":\"кріогідратів\",\"memberships\":[\"uk\"]},{\"word\":\"діагенезом\",\"memberships\":[\"uk\"]},{\"word\":\"одкочено\",\"memberships\":[\"uk\"]},{\"word\":\"незім'яте\",\"memberships\":[\"uk\"]},{\"word\":\"присмирённая\",\"memberships\":[\"ru\"]},{\"word\":\"списались\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"аминбаевны\",\"memberships\":[\"ru\"]},{\"word\":\"прорубишься\",\"memberships\":[\"ru\"]},{\"word\":\"ковыляниями\",\"memberships\":[\"ru\"]},{\"word\":\"припоминаньи\",\"memberships\":[\"ru\"]},{\"word\":\"оплёвывающуюся\",\"memberships\":[\"ru\"]},{\"word\":\"ильменским\",\"memberships\":[\"ru\"]},{\"word\":\"донецки\",\"memberships\":[\"ru\"]},{\"word\":\"пожалевши\",\"memberships\":[\"ru\"]},{\"word\":\"простерёгшего\",\"memberships\":[\"ru\"]},{\"word\":\"воспринимала\",\"memberships\":[\"ru\"]},{\"word\":\"зарумянивших\",\"memberships\":[\"ru\"]},{\"word\":\"лилиянн\",\"memberships\":[\"ru\"]},{\"word\":\"переволочило\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"картофелесортировальных\",\"memberships\":[\"ru\"]},{\"word\":\"низлагаемы\",\"memberships\":[\"ru\"]},{\"word\":\"питиримах\",\"memberships\":[\"ru\"]},{\"word\":\"безмельницыны\",\"memberships\":[\"ru\"]},{\"word\":\"иносказательно\",\"memberships\":[\"ru\"]},{\"word\":\"петрунелями\",\"memberships\":[\"ru\"]},{\"word\":\"антитеатру\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"синевато-сером\",\"memberships\":[\"ru\"]},{\"word\":\"посахаренную\",\"memberships\":[\"ru\"]},{\"word\":\"истолковываемое\",\"memberships\":[\"ru\"]},{\"word\":\"тяготимому\",\"memberships\":[\"ru\"]},{\"word\":\"отсасываемых\",\"memberships\":[\"ru\"]},{\"word\":\"саживаешь\",\"memberships\":[\"ru\"]},{\"word\":\"поточенной\",\"memberships\":[\"ru\"]},{\"word\":\"зашлифовывала\",\"memberships\":[\"ru\"]},{\"word\":\"кудесниками\",\"memberships\":[\"ru\"]},{\"word\":\"взаимопроникающего\",\"memberships\":[\"ru\"]},{\"word\":\"небесно-голубому\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"нордах\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"затекли\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"спохватитесь\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"кольчуги\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"скверна\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"шапочками\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"питого\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"зашушукайтесь\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"камуфляже\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"уколупнули\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"полонянка\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"тумаком\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"контрпропагандою\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"маликам\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"червоточиною\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"тугрику\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"дискомфортах\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"конденсорами\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"секуляризуй\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"поморочило\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"блефуй\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"скрипни\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"плющена\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"термосифонною\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"обагритесь\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"лонам\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"черпав\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"неоген\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"перешитому\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"фталазолом\",\"memberships\":[\"ru\",\"uk\"]},{\"word\":\"латникам\",\"memberships\":[\"ru\",\"uk\"]}]\n\n\ndef native_membership_installed_probe():\n    \"\"\"Readonly installed-resource measurements; no speech/driver/data mutation.\"\"\"\n    def require(name,condition,**details):\n        check(\"native_membership_\"+name,\"passed\" if condition else \"failed\",**details)\n        if not condition:\n            raise ValueError(\"Installed native membership invariant: \"+name)\n    import math\n    manager=sys.modules.get(\"_dordiai_main_native_membership_runtime\")\n    require(\"singleton\",manager is not None and getattr(DRIVER,\"_native_membership_runtime\",None) is manager)\n    resource=manager._resource\n    require(\"active_owned_lease\",resource is not None and resource.enabled and not resource.closed and\n        getattr(DRIVER,\"_native_membership_token\",None) in manager._leases and manager._maintenance is None,\n        active_leases=len(manager._leases))\n    reader=resource.reader\n    path=str(resource.dataset)\n    require(\"actual_installed_long_namespace\",len(path)>260 and path.startswith(\"\\\\\\\\?\\\\\"),\n        dataset_path=path,path_characters=len(path),external_candidate_used=False)\n    statistics=reader.statistics()\n    require(\"trusted_dataset\",statistics[\"dataset_sha256\"]==\"21208748a50ebf3f5dd3e2feb94f0f3caf3490c2be784aaca2209462380e6689\" and\n        statistics[\"word_count\"]==6642550 and tuple(statistics[\"codes\"])==(\"uk\",\"ru\"),statistics=statistics)\n    reader.verify_current()\n    driver_module=sys.modules[type(DRIVER).__module__]\n    speech_module=driver_module._speech_text\n    wide_module=driver_module._wide\n    rows=[]\n    for case in NATIVE_SOURCE_CASES:\n        expected=frozenset(case[\"memberships\"])\n        word=case[\"word\"]\n        via_manager=frozenset(manager.candidates(word))\n        via_reader=frozenset(reader.candidates(word))\n        via_speech=frozenset(speech_module.cyrillic_word_candidates(word))\n        via_wide=frozenset(wide_module._lexical_candidates(word,\"cyrillic\"))&{\"uk\",\"ru\"}\n        rows.append({\"word\":word,\"expected\":sorted(expected),\"manager\":sorted(via_manager),\n            \"reader\":sorted(via_reader),\"speech_candidates\":sorted(via_speech),\"wide_core_candidates\":sorted(via_wide),\n            \"passed\":all(actual==expected for actual in (via_manager,via_reader,via_speech,via_wide))})\n    require(\"unknown_finite_membership\",not manager.candidates(\"invalid control with spaces\") and\n        not reader.candidates(\"invalid control with spaces\"),\n        scope=\"Finite dictionary abstention only; downstream legacy routing remains separate\")\n    RESULT[\"native_membership\"]={\"scope\":\"Actual installed manager and both candidate wrappers; not pronunciation or intended-language proof\",\n        \"source_cases\":rows,\"archive_modified\":False,\"dataset_modified\":False,\n        \"production_word_route_verified\":False,\"physical_audio_verified\":False}\n    require(\"source_membership_and_wrappers\",len(rows)==96 and all(row[\"passed\"] for row in rows),case_count=len(rows))\n    def measure(function,count):\n        durations=[]\n        started=time.perf_counter_ns()\n        for i in range(count):\n            case=NATIVE_SOURCE_CASES[i%len(NATIVE_SOURCE_CASES)]\n            tick=time.perf_counter_ns()\n            actual=frozenset(function(case[\"word\"]))\n            elapsed=(time.perf_counter_ns()-tick)/1000000.0\n            if actual!=frozenset(case[\"memberships\"]):\n                raise ValueError(\"Installed manager lookup changed during measurement\")\n            durations.append(elapsed)\n        total=(time.perf_counter_ns()-started)/1000000.0\n        ordered=sorted(durations)\n        return {\"count\":count,\"median_ms\":(ordered[(count-1)//2]+ordered[count//2])/2,\"p95_ms\":ordered[math.ceil(count*.95)-1],\n            \"max_ms\":ordered[-1],\"total_ms\":total,\"workload\":\"mixed96 source-selected forms, repeated; warm source resource, no storage-cache eviction\"}\n    # No background speech, config changes, lease release or cache bypass.\n    results={}\n    for count in (100,1000):\n        results[\"reader_\"+str(count)]=measure(reader.candidates,count)\n        results[\"manager_\"+str(count)]=measure(manager.candidates,count)\n    RESULT[\"native_membership\"][\"lookup_timings\"]=results\n    RESULT[\"native_membership\"][\"statistics_after\"]=reader.statistics()\n    reader.verify_current()\n    require(\"readonly_probe_completed\",manager._resource is resource and\n        getattr(DRIVER,\"_native_membership_token\",None) in manager._leases and not resource.closed,\n        resource_or_driver_closed_by_probe=False)\n\n"
ANCHOR='    check("select_dordiai", "passed", driver_name=DRIVER.name)\n'


def install_membership_observer(base):
    original=base.PROBE_PLUGIN
    if original.count(ANCHOR)!=1 or "def native_membership_installed_probe(" in original:
        raise ValueError("Actual NVDA probe anchor differs; refusing stale instrumentation")
    insertion=ANCHOR+(
        '    try:\n'
        '        native_membership_installed_probe()\n'
        '    except Exception as error:\n'
        '        check("native_membership_probe_exception", "failed", error_type=type(error).__name__)\n'
        '        finish()\n'
        '        return\n')
    candidate=original.replace(ANCHOR,insertion,1)+PROBE_FUNCTION
    compile(candidate.replace("__PROBE_SETTINGS__",repr({})).replace("__NATIVE_IMPORT_DIAGNOSTIC__",repr("")),"installed-native-membership-probe","exec")
    base.PROBE_PLUGIN=candidate
    return original


def main(argv=None):
    spec=importlib.util.spec_from_file_location("_dordiai_actual_installed_membership_controller",
        Path(__file__).with_name("windows_nvda_probe.py"))
    base=importlib.util.module_from_spec(spec)
    spec.loader.exec_module(base)
    install_membership_observer(base)
    return base.main(argv)


if __name__=="__main__":
    raise SystemExit(main())
